import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { handleError, handleSuccess } from "../utils";
import { ToastContainer } from "react-toastify";

// import css
import '../assets/css/home.css';

function Home() {
  const [loggedInUser, setLoggedInUser] = useState("");
  const [products, setProducts] = useState("");
  const [isProfileVisible, setIsProfileVisible] = useState(false); // New state for toggling profile visibility
  const navigate = useNavigate();

  useEffect(() => {
    setLoggedInUser(localStorage.getItem("loggedInUser"));
  }, []);

  const handleLogout = (e) => {
    localStorage.removeItem("token");
    localStorage.removeItem("loggedInUser");
    handleSuccess("User Loggedout");
    setTimeout(() => {
      navigate("/login");
    }, 1000);
  };

  const fetchProducts = async () => {
    try {
      const url = "http://localhost:3001/products";
      const headers = {
        headers: {
          Authorization: localStorage.getItem("token"),
        },
      };
      const response = await fetch(url, headers);
      const result = await response.json();
      console.log(result);
      setProducts(result);
    } catch (err) {
      handleError(err);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  const toggleProfileVisibility = () => {
    setIsProfileVisible(prevState => !prevState); // Toggle the visibility
  };

  return (
    <div>
      <div className="home-page">
        <nav>
          <div className="navbar">
            <div className="leftelement">
              <div className="left element1">Logo</div>
              <div className="left element2">Appointment</div>
              <div className="left element3">Consultations</div>
              <div className="left element4">Option</div>
              <div className="left element5">Online detailing</div>
            </div>
            <div className="rightelement">
              <div className="rightelement1">
                <img
                  src="https://cdn-icons-png.flaticon.com/128/8861/8861125.png"
                  alt="add patient logo"
                  width="20"
                  height="20"
                />
              </div>
              <div className="rightelement2">Search Option</div>
              <div className="rightelement3">
                <img
                  src="https://cdn-icons-png.flaticon.com/128/18472/18472635.png"
                  alt="menu"
                  width="20"
                  height="20"
                />
              </div>
              <div className="rightelement4" onClick={toggleProfileVisibility}> {/* Add click handler */}
                <img
                  src="https://cdn-icons-png.flaticon.com/128/456/456283.png"
                  alt="user logo"
                  width="20"
                  height="20"
                  className="userData"
                />
                {isProfileVisible && ( 
                  <div className="profile">
                    <h1>Welcome, {loggedInUser}</h1>
                    <button onClick={handleLogout}>Logout</button>
                  </div>
                )}
              </div>
            </div>
          </div>
        </nav>
      </div>
      <ToastContainer />
    </div>
  );
}

export default Home;
